graph = [['N' for _ in range(n)] for _ in range(n)]

# Set the diagonal to 'N'
for i in range(n):
    graph[i][i] = 'N'

# Fill the adjacency matrix to ensure there are exactly k shortest paths
for i in range(1, n - 1):
    for j in range(i + 1, n):
        graph[i][j] = 'Y'
        graph[j][i] = 'Y'

# Calculate the number of paths using the adjacency matrix
def count_paths(graph):
    n = len(graph)
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if graph[i][j] == 'Y':
                dist[i][j] = 1
            if i == j:
                dist[i][j] = 0

    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    count = 0
    for i in range(n):
        if dist[0][i] + dist[i][1] == dist[0][1]:
            count += 1
    return count

# Check if the graph has exactly k shortest paths
if count_paths(graph) == k:
    print(n)
